'use strict';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = v => Number(String(v).replaceAll(',','')).toLocaleString('en-US');
const number = v => Number(String(v).replaceAll(',',''));
const E1 = DATA.experiments.exp1, E2 = DATA.experiments.exp2;
const source = (file, label='Read source', match='') => `<button class="text-link" data-source="${esc(file)}" data-match="${esc(match)}">${esc(label)} ↗</button>`;
const evidence = (id,label) => `<button class="text-link" data-evidence="${id}">${esc(label)} ↗</button>`;
const tag = (text,cls='') => `<span class="tag ${cls}">${text}</span>`;
const scoreDots = (passed,total) => `<div class="score-dots" role="img" aria-label="${passed} of ${total} applicable checks passed">${Array.from({length:total},(_,i)=>`<span aria-hidden="true" class="score-dot ${i>=passed?'bad':''}"></span>`).join('')}</div>`;
const roleCard = (key,name,initials,job,meta) => `<div class="role-card ${key}"><span class="avatar" aria-hidden="true">${initials}</span><h3>${name}</h3><p>${job}</p><small>${meta}</small><button class="text-link" data-role="${key}">Explore role ↗</button></div>`;
const steps = (lit) => `<div class="stage-strip" aria-label="Stages highlighted: ${lit.join(', ')}">${['S1','S2a','S2b','S3','S4','S5','S6','S7'].map(x=>`<span class="${lit.includes(x)?'lit':''}">${x}</span>`).join('')}</div>`;
