let scene=0,view='story',playing=false,timer=null,experiment='exp1',caseFilter='all',collection='lessons',rawExport=null;
function pause(){playing=false;clearTimeout(timer);$('#play').textContent='Play story';$('#play').setAttribute('aria-pressed','false');}
function play(){if(playing){pause();return}if(scene===scenes.length-1)scene=0;playing=true;renderScene();$('#play').textContent='Pause story';$('#play').setAttribute('aria-pressed','true');schedule();}
function schedule(){clearTimeout(timer);if(playing)timer=setTimeout(()=>{if(scene<scenes.length-1){scene++;renderScene();schedule()}else pause()},18000);}
function goScene(i){pause();scene=Math.max(0,Math.min(scenes.length-1,i));showView('story',false);renderScene();if(!document.body.classList.contains('presenting'))$('.story-shell').scrollIntoView({block:'start',behavior:'instant'});else $('.story-workspace').scrollTop=0;}
function renderScene(){const s=scenes[scene];$('#scene-kicker').textContent=s.kicker;$('#scene-title').textContent=s.title;$('#scene-description').textContent=s.description;$('#scene-takeaway').textContent=s.takeaway;$('#scene-counter').textContent=`${String(scene+1).padStart(2,'0')} / ${scenes.length}`;$('#scene-visual').innerHTML=s.render();$('#chapters').innerHTML=scenes.map((x,i)=>`<button class="chapter ${i===scene?'active':''}" data-scene="${i}" ${i===scene?'aria-current="step"':''} aria-label="Chapter ${i+1}: ${esc(x.nav)}"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="chapter-label">${esc(x.nav)}</span></button>`).join('');$('#prev').disabled=scene===0;$('#next').textContent=scene===scenes.length-1?'Replay from start ↺':'Next chapter →';$('#announcement').textContent=`Chapter ${scene+1}. ${s.title}`;history.replaceState(null,'',`#story-${scene+1}`);}
function showView(v,scroll=true){if(!['story','results','database','sources'].includes(v))return;view=v;if(v!=='story')pause();['story','results','database','sources'].forEach(x=>$(`#${x}-view`).hidden=x!==v);$$('.topnav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);if(b.dataset.view===v)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(v==='results')renderResults();if(v==='database')renderDatabase();if(v==='sources')renderSources();history.replaceState(null,'',v==='story'?`#story-${scene+1}`:`#${v}`);if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function openDrawer(title,html,kicker='SOURCE RECORD'){pause();$('#drawer-title').textContent=title;$('#drawer-kicker').textContent=kicker;$('#drawer-content').innerHTML=html;$('#drawer').showModal();$('#drawer-content').scrollTop=0;}
function openSource(file,match=''){const text=DATA.sources[file];if(!text)return;const lines=text.split('\n');let idx=match?lines.findIndex(l=>l.includes(match)):0;if(idx<0)idx=0;const start=match?Math.max(0,idx-1):0;const end=match?Math.min(lines.length,idx+45):lines.length;openDrawer(file,`<p class="source-meta">Bundled repository snapshot <code>${DATA.commit.slice(0,7)}</code>. Lines ${start+1}–${end} of ${lines.length}.</p><a href="${DATA.repo}/blob/${DATA.commit}/${file}#L${idx+1}" target="_blank" rel="noopener">Open this source on GitHub ↗</a><div class="source-file">${lines.slice(start,end).map((l,i)=>`<div class="line-source"><span>${start+i+1}</span><span>${esc(l)||' '}</span></div>`).join('')}</div>`,'REPOSITORY SOURCE');}
function openRole(id){const r=roles[id];if(!r)return;const c=DATA.config.context_policy.roles[r.role];openDrawer(r.name,`<div class="role-card ${id}"><span class="avatar">${r.initials}</span><h3>${r.job}</h3><p>${r.stages}</p></div><h3>What this role receives</h3><p>${r.detail}</p>${c?`<pre><code>${esc(JSON.stringify(c,null,2))}</code></pre>`:''}<p class="info-note">This explains the configured workflow. It is not invented dialogue or evidence that a specific statement was made in a particular call.</p>${source(r.source,'Read source configuration',id==='ia'?'def propose':'"context_policy"')}`,'AGENT ROLE');}
function openEvidence(id){
 const report1=source('reports/exp1.md','Open Experiment 1 report','## Analyze'),report2=source('reports/exp2.md','Open Experiment 2 report','## Improve');
 if(id==='coverage'){openCoverage();return}
 if(id==='why')openDrawer('Why the citation defect escaped',`<p>Verbatim Analyze artifact from Experiment 1. These are the improvement agent’s recorded causal statements.</p><div class="whys">${E1.lesson.why.map(t=>`<div class="why"><p>${esc(t)}</p></div>`).join('')}</div><h3>Origin event</h3><code>${E1.lesson.origin}</code><h3>Source events</h3><pre>${E1.lesson.refs.map(esc).join('\n')}</pre>${report1}`,'IMPROVEMENT AGENT · RECORDED ANALYSIS');
 else if(id==='lesson')openDrawer('The verified Experiment 1 lesson',`<p><code>${E1.lesson.id}</code></p><blockquote>${esc(E1.lesson.text)}</blockquote><div class="ruling-row">${tag('status: verified','good')}${tag('cause: measurement','good')}${tag('controllable: true','good')}${tag('snapshot: M1','good')}</div><h3>From record to retrieval</h3><p>The lesson document links the E7 defect to a why-chain, an origin event, and supporting event IDs. The store embeds the lesson text. Later queries can retrieve verified lessons by scope and memory snapshot.</p>${report1}${source('adaptive_harness/store/records.py','Read lesson storage code','def save_lesson')}`,'lessons · EXACT LESSON TEXT');
 else if(id==='proposal1'||id==='proposal2'){const e=id==='proposal1'?E1:E2;openDrawer(`Candidate ${e.candidate}: the recorded proposal`,`<p>Exact text from the Improve artifact. The improvement agent proposed this configuration change; code validated and tested it.</p><div class="patch">${esc(e.proposal.changes[0].path)}<br><b>${esc(e.proposal.changes[0].value)}</b></div><h3>Why this change</h3><blockquote>${esc(e.proposal.changes[0].why)}</blockquote><h3>Rationale</h3><blockquote>${esc(e.proposal.rationale)}</blockquote><h3>Expected effect</h3><blockquote>${esc(e.proposal.expected)}</blockquote><h3>Risks</h3><blockquote>${esc(e.proposal.risks)}</blockquote>${source(`reports/${e.id}.md`,'Open the original report','### Proposal\n')}`,'IMPROVEMENT AGENT · RECORDED PROPOSAL');}
 else if(id==='escape')openDrawer('The events cited by the analysis',`<p>Report-backed excerpts for run <code>D2-20260926T155855-9c8fbc</code>. The full event documents are not bundled with the public report.</p><div class="doc-fields"><div class="doc-field"><span>00037 · S6 brief</span><span>Analysis reports a flat evidence list mixing race data results 00014, 00017, 00022 with interval computations 00027, 00030, 00033.</span></div><div class="doc-field"><span>00038 · S7 check</span><span>Exact content reproduced in the report:<pre>{"check": "schema", "passed": true, "reasons": []}</pre></span></div><div class="doc-field"><span>00039 · decision</span><span>The analysis records GO with no per-row citation validation.</span></div></div>${report1}`,'EVENT REFERENCES · FROM THE REPORT');
 else if(id==='calls')openDrawer('D2 baseline: measured call usage',`<p>Run <code>D2-20260926T155855-9c8fbc</code>, Experiment 1.</p><div class="doc-fields">${[['model calls','16'],['tool calls','6'],['input tokens','46,209'],['output tokens','21,230'],['cache-read tokens','54,280'],['wall time','205.6 seconds']].map(([a,b])=>`<div class="doc-field"><span>${a}</span><span>${b}</span></div>`).join('')}</div><p>Input includes prompt-cache writes, but excludes cache reads. These are recorded provider counts, not cost estimates.</p>${source('reports/exp1.md','See the baseline cost table','### Cost per baseline run')}${source('adaptive_harness/runner/coordinator.py','What each model_call stores','def _ask')}`,'RECORDED API USAGE');
 else if(id==='history')openDrawer('The memory of the rejected proposal',`<p>Experiment 2’s report explicitly records the history shown to the improvement agent.</p><div class="patch">v2 · rejected<br>replace /checks/venue_match/enabled = true<br>R2: candidate worst 11, current best 11</div><p>The agent receives development-case outcomes. The code withholds held-out and control details from its prompt and rejects an exact repeat of a rejected change set.</p><div class="human-change">The operator added proposal-history support between the two cycles. The agent did not autonomously rewrite the improvement process.</div>${source('reports/exp2.md','Read the recorded history','### Proposal history')}${source('reports/exp2.notes.json','Read operator provenance')}`,'harness_versions + experiments');
 else if(id==='objection')openDrawer('A disagreement persisted into the brief',`<p>These are exact excerpts from the recorded improvement proposals, not the missing S3 transcript.</p><h3>Experiment 1</h3><blockquote>The D2 brief did carry an SC source-mismatch objection, but the E7 root cause is about citations, not source agreement, and extra HOLD triggers could cost other checks without addressing E7.</blockquote><h3>Experiment 2</h3><blockquote>Both failing D2 runs recorded an open objection that the two sources disagree on the safety car.</blockquote>${source('reports/exp1.md','Experiment 1 rationale','- Rationale:')}${source('reports/exp2.md','Experiment 2 rationale','- Rationale:')}`,'RECORDED PROPOSAL EXCERPTS');
 else if(id==='baseline2')openDrawer('A fresh starting run in Experiment 2',`<p>The baseline was rerun under pinned v1 and memory M0. It was not a continuation of candidate v2.</p><p>D2 run: <code>D2-20260926T164658-a1fb27</code></p><div class="doc-fields"><div class="doc-field"><span>00029 · S6</span><span>A flat top-level evidence list again lacked the required row citation.</span></div><div class="doc-field"><span>00030 · S7</span><span>Schema check passed.</span></div><div class="doc-field"><span>00031 · decision</span><span>GO. E7 subsequently failed.</span></div></div><blockquote>${esc(E2.lesson.text)}</blockquote>${source('reports/exp2.md','Read the repeated finding','## Analyze')}`,'EXPERIMENT 2 · BASELINE EVIDENCE');
}
function openCoverage(){openDrawer('What is recorded, and what is explained',`<h3>Included in this presentation</h3><p>The two generated MongoDB reports, all 36 run IDs, 72 applicable check rows across the two experiments, call counts, exact improvement-agent lesson and proposal text, and the recorded acceptance decisions. The code and configuration sources explain the role handoffs and storage.</p><h3>Not present in the public repository</h3><p>The complete model requests and responses, S1–S6 dialogue, tool payloads, context manifests, and raw MongoDB documents. The walkthrough labels its workflow summaries and uses quotations only for text actually reproduced in the reports.</p><h3>Read the complete conversations</h3><p>A read-only export of the two experiments can be loaded in the Evidence view. The provided export helper retrieves only the matching runs, events, evaluations, experiments, referenced lessons, and v1–v3. No model is called and no database records are changed.</p><button class="primary" data-action="goto-evidence">Open Evidence view →</button><h3>What “learning” means here</h3><p>Stored lessons and proposal history change what is supplied as context and what configuration gets tested. There is no evidence here of model retraining or weight updates. Both candidates were rejected.</p>`,'PROVENANCE & COVERAGE');}

function renderResults(){const e=DATA.experiments[experiment];const totalCalls=e.cost.reduce((s,r)=>s+number(r['model calls']),0),totalTools=e.cost.reduce((s,r)=>s+number(r['tool calls']),0);$('#results-view').innerHTML=`
 <div class="view-heading"><div><p class="eyebrow">THE FIXED EVALUATOR’S RECORD</p><h1>What actually changed?</h1><p>Compare every applicable check. The acceptance comparison is <strong>memory only versus candidate</strong>, both on M1.</p></div><div class="segmented" aria-label="Choose experiment">${['exp1','exp2'].map((id,i)=>`<button data-experiment="${id}" class="${experiment===id?'active':''}" aria-pressed="${experiment===id}">Experiment ${i+1}</button>`).join('')}</div></div>
 <div class="summary-grid"><div class="summary"><span class="tiny-label">DEVELOPMENT · CURRENT → CANDIDATE</span><strong>11 → 11</strong><p>12 applicable checks in each arm.</p></div><div class="summary"><span class="tiny-label">CANDIDATE ${e.candidate}</span><strong style="color:var(--red)">Rejected</strong><p>R2 requires strictly more checks passed.</p></div><div class="summary"><span class="tiny-label">PINNED CONFIGURATION</span><strong>v1</strong><p>Control phase not reached.</p></div></div>
 <h3>Five rules. All must hold.</h3><div class="table-wrap"><table><thead><tr><th>Rule</th><th>Result</th><th>Recorded detail</th></tr></thead><tbody>${e.rules.map(r=>`<tr><td>${r.rule} · ${({R0:'Validity',R1:'No control regression',R2:'Development improvement',R3:'Held-out performance',R4:'Runtime'})[r.rule]}</td><td class="${r.holds.includes('no')?'fail':'pass'}">${r.holds.includes('no')?'FAIL':'PASS'}</td><td>${esc(r.detail)}</td></tr>`).join('')}</tbody></table></div>
 <div class="table-controls"><h3>Checks by case and arm</h3><label class="muted" for="case-filter">Show </label><select id="case-filter"><option value="all" ${caseFilter==='all'?'selected':''}>All six cases</option><option value="D2" ${caseFilter==='D2'?'selected':''}>D2: the learned defect</option><option value="E7" ${caseFilter==='E7'?'selected':''}>E7: evidence across cases</option><option value="changed" ${caseFilter==='changed'?'selected':''}>Differences between arms</option></select></div>
 <div class="table-wrap"><table><thead><tr><th>Case</th><th>Set</th><th>Check</th><th>Baseline<br>v1 + M0</th><th>Memory only<br>v1 + M1</th><th>Candidate<br>${e.candidate} + M1</th></tr></thead><tbody>${e.scoreRows.filter(r=>caseFilter==='all'||caseFilter==='D2'&&r.case==='D2'||caseFilter==='E7'&&r.check.startsWith('E7')||caseFilter==='changed'&&new Set(Object.values(r).slice(3)).size>1).map(r=>{const vals=Object.values(r);return `<tr><td>${r.case}</td><td class="group">${esc(r.set.replace('_',' '))}</td><td>${esc(r.check.replace(' ◆',''))}</td>${vals.slice(3).map(v=>`<td class="${v==='PASS'?'pass':v==='FAIL'?'fail':'na'}">${v==='PASS'?'✓ PASS':v==='FAIL'?'× FAIL':esc(v)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>
 <p class="info-note">D1, H1 and P1 are venue briefs with 8 applicable checks. D2, H2 and P2 are race audits with 4. Each arm has 36 opportunities. Counts come from one run per case per arm; these are not estimates of a reliable improvement rate.</p>
 <div class="table-controls"><h3>What the runs consumed</h3><span class="muted">${fmt(totalCalls)} model calls · ${fmt(totalTools)} tool calls</span></div><div class="cost-grid">${e.cost.map((r,i)=>`<div><h3>${['Baseline','Memory only','Candidate'][i]}</h3><div class="bar-row"><div><span>Model calls</span><strong>${r['model calls']}</strong></div><div class="bar"><span style="width:${number(r['model calls'])/130*100}%"></span></div><small>${r['tool calls']} tool calls</small></div><div class="bar-row"><div><span>Runtime</span><strong>${r['wall s']} s</strong></div><small>Sum of case runtimes</small></div><div class="bar-row"><div><span>Input / output tokens</span></div><strong class="mono">${r.input} / ${r.output}</strong><small>Cache reads: ${r['cache read']}</small></div></div>`).join('')}</div>
 <p class="info-note">Arm totals exclude the separate improvement agent’s Define, Analyze and Improve calls. Cache reads are separate from input tokens. No dollar cost is inferred.</p>
 <details><summary class="text-link">Open the 18 run records</summary><div class="table-wrap"><table><thead><tr><th>Arm</th><th>Case</th><th>Run ID</th><th>Status</th></tr></thead><tbody>${e.runs.map(r=>`<tr><td>${esc(r.arm.replace('_',' '))}</td><td>${r.case}</td><td><button class="text-link mono" data-run="${r['run id']}">${r['run id']} ↗</button></td><td>${r.status}</td></tr>`).join('')}</tbody></table></div></details>
 <div class="source-row">${source(`reports/${e.id}.md`,'Open original experiment report')}${source('SPECIFICATION.md','Read the acceptance specification','## Acceptance rules')}</div>`;}

const collections={
 runs:{label:'The unit of work',why:'One document for each case run. This links the experiment, trial arm, configuration, memory snapshot, model assignment, runtime, and final output.',fields:()=>[['run_id','D2-20260926T155855-9c8fbc'],['experiment_id','exp1'],['arm','baseline'],['case_id','D2'],['harness_version','v1'],['memory_snapshot','M0'],['status','completed'],['model_calls','16'],['tool_calls','6']],note:'Selected fields reconstructed from the report. The raw run document is not included in the public repository.',next:'Use run_id to retrieve its ordered events and evaluator results.'},
 events:{label:'What happened, in order',why:'Model requests and responses, tool calls and results, stage messages, checks, decisions, and errors become separate events. References connect their provenance.',fields:()=>[['_id','D2-20260926T155855-9c8fbc:00038'],['stage_id','S7'],['type','check'],['content','{"check":"schema","passed":true,"reasons":[]}']],note:'This event’s content is quoted exactly in the Analyze report. Other event metadata and complete conversations require the raw records.',next:'The Analyze phase follows event references to identify where the citation defect escaped.'},
 evaluations:{label:'The independent verdict',why:'The fixed evaluator records each applicable check verdict with the run ID and measurement hashes. It runs separately from the team that wrote the brief.',fields:()=>[['run_id','D2-20260926T155855-9c8fbc'],['E1 schema','PASS'],['E4 indicators','PASS'],['E7 evidence','FAIL · evidence_missing'],['E8 budget','PASS'],['E2 / E3 / E5 / E6','Not applicable to a race audit']],note:'A readable projection of the recorded score table, not the serialized evaluation document.',next:'Only development-case defects can feed Define, Analyze, and the improvement agent’s prompt.'},
 lessons:{label:'The reusable root cause',why:'A lesson preserves the defect, the causal explanation, and the events supporting it. Its text is embedded for Atlas Vector Search.',fields:()=>[['_id',E1.lesson.id],['cause_category','measurement'],['status','verified'],['controllable','true'],['snapshot','M1'],['origin_event_id',E1.lesson.origin],['text',E1.lesson.text]],note:'Report-derived fields. Embedding values and other unreported fields are not invented.',next:'Retrieve verified, controllable lessons on M1 for the improvement agent. Configured first-stage role contexts can also receive eligible lessons.'},
 harness_versions:{label:'What was proposed',why:'The version document keeps the configuration, its parent, its lesson-linked changes, validation, status, and decision reasons. Rejection does not erase the proposal.',fields:()=>[['_id','v2'],['parent_id','v1'],['change','replace /checks/venue_match/enabled = true'],['lesson_id',E1.lesson.id],['status','rejected'],['pinned','false'],['decision reason','R2: candidate worst 11, current best 11']],note:'Selected report-backed fields. v1 remains the only pinned version.',next:'Proposal-history support makes the earlier change and its development outcome visible in Experiment 2.'},
 experiments:{label:'How the trial was decided',why:'One document ties together the cases, runs grouped by arm, phase artifacts, pass-or-stop decisions, acceptance results, and the final decision.',fields:()=>[['_id','exp1'],['cases','D1, D2, H1, H2, P1, P2'],['arms','baseline: v1 + M0; memory_only: v1 + M1; candidate: v2 + M1'],['define / measure / analyze','Passed'],['improve','Stopped: R2 failed'],['control','Not reached'],['decision','rejected']],note:'Readable report projection. The stored record retains more detailed artifacts and call metadata.',next:'The next experiment gets fresh run records. The previous rejection remains available as proposal history.'},
};
function renderDatabase(){const c=collections[collection];$('#database-view').innerHTML=`<div class="view-heading"><div><p class="eyebrow">MONGODB ATLAS / SIX COLLECTIONS</p><h1>Memory you can follow.</h1><p>Click a collection to see what it contributes. These are report-backed field views of the same D2 story.</p></div></div><div class="mongo-layout"><div class="collection-list" aria-label="MongoDB collections">${Object.entries(collections).map(([k,v])=>`<button data-collection="${k}" class="${k===collection?'active':''}" aria-pressed="${k===collection}"><strong>${k}</strong><small>${v.label}</small></button>`).join('')}</div><article class="collection-detail"><p class="eyebrow">${collection}</p><h2>${c.label}</h2><p>${c.why}</p><div class="doc-fields">${c.fields().map(([k,v])=>`<div class="doc-field"><span>${esc(k)}</span><span>${esc(v)}</span></div>`).join('')}</div><p class="definition">${c.note}</p><h3>How the next step uses it</h3><p>${c.next}</p><div class="source-row">${source('CONTRACT.md','Collection contract','## C. MongoDB collections')}${source('reports/exp1.md','Experiment 1 evidence','## Analyze')}${collection==='lessons'?source('adaptive_harness/store/mongo.py','Inspect the vector query','def vector_search_pipeline'):''}</div></article></div><div class="source-card"><h3>Retrieval is not retraining</h3><p>The lesson text is embedded and retrieved as context. The role models’ weights do not change. In Experiment 2, the new proposal also receives the rejected v2 change and its development-case outcome.</p><div class="flow"><div class="flow-block"><span class="tiny-label">LESSON LOOKUP</span><h3>Atlas Vector Search</h3><p>Verified lesson + scope + M1 snapshot → relevant root causes.</p></div><span class="flow-arrow" aria-hidden="true">+</span><div class="flow-block"><span class="tiny-label">PROPOSAL HISTORY</span><h3>Past changes and decisions</h3><p>v2 rejected on development improvement → avoid repeating the same patch.</p></div><span class="flow-arrow" aria-hidden="true">→</span><div class="flow-block"><span class="tiny-label">MODEL CONTEXT</span><h3>Experiment 2 proposal</h3><p>The agent proposes source_agreement for v3, derived from v1.</p></div></div></div>`;}
function renderSources(){const named={'reports/exp1.md':'Experiment 1: generated MongoDB report','reports/exp2.md':'Experiment 2: generated MongoDB report','reports/exp2.notes.json':'Operator change between experiments','configs/v1.json':'Roles, stages and context policy','SPECIFICATION.md':'Fixed grading and acceptance rules','adaptive_harness/dmaic/history.py':'How prior rejected proposals reach the next prompt','adaptive_harness/dmaic/improve.py':'Lesson retrieval, proposal and trial','adaptive_harness/runner/coordinator.py':'Model calls, tools, checks and repair','adaptive_harness/runner/context.py':'The context provided to each role','adaptive_harness/store/mongo.py':'MongoDB storage and vector retrieval'};$('#sources-view').innerHTML=`<div class="view-heading"><div><p class="eyebrow">PROVENANCE / INSPECT THE RECORD</p><h1>The story has receipts.</h1><p>Every result and quotation is grounded in the repository snapshot. Open a source to inspect the bundled text, or follow its link to the exact Git commit.</p></div></div><div class="source-card"><h3>What this version can show</h3><p>Actual trial results, event references, exact lesson and proposal text, plus labeled explanations of the configured workflow. The public reports do not contain the complete S1–S6 conversations or model-call payloads.</p><button class="quiet" data-action="coverage">Read evidence coverage</button><a href="${DATA.repo}/tree/${DATA.commit}" target="_blank" rel="noopener">Repository snapshot ${DATA.commit.slice(0,7)} ↗</a></div><div class="source-card"><h3>Load the complete MongoDB record</h3><p>Load a JSON export made with the accompanying read-only helper. It stays in this browser tab. Once loaded, open any run in Results to inspect the exact API responses, messages, tool results and context manifests.</p><label class="quiet" style="display:inline-block;cursor:pointer" for="trace-file">Choose experiment export<input id="trace-file" type="file" accept=".json,application/json" class="sr-only"></label><p id="import-status" class="info-note" role="status" style="margin-top:14px">${rawExport?`${rawExport.runs.length} runs and ${rawExport.events.length} events loaded locally.`:'No raw trace loaded. Report evidence remains available.'}</p></div><div class="source-list">${Object.entries(named).map(([k,v])=>`<button class="source-item" data-source="${k}"><strong>${v}</strong><small>${k} ↗</small></button>`).join('')}</div><div class="source-card"><h3>Scope of the claim</h3><p>Both candidates were rejected. No deployment or model-weight improvement is claimed. There were six cases and one run per case per arm. Held-out and control evidence stayed outside the improvement agent’s learning prompt. The operator’s proposal-history code change is shown explicitly.</p></div>`;}
function openRun(runId){let exp,r;for(const e of Object.values(DATA.experiments)){const match=e.runs.find(x=>x['run id']===runId);if(match){exp=e;r=match;break}}if(!r)return;let evts=rawExport?.events.filter(e=>e.run_id===runId).sort((a,b)=>a.seq-b.seq)||[];const record=rawExport?.runs.find(r=>r._id===runId);openDrawer(`${exp.id} · ${r.case} · ${r.arm.replace('_',' ')}`,`<p><code>${runId}</code></p><div class="ruling-row">${tag(`status: ${r.status}`)}${tag(`configuration: ${r.arm==='candidate'?exp.candidate:'v1'}`)}${tag(`memory: ${r.arm==='baseline'?'M0':'M1'}`)}</div>${evts.length?`<h3>${evts.length} recorded events</h3><p>Exact stored event content. Model-call records include the request and response. Message events contain the parsed stage output. This view uses the local export you loaded.</p><label for="event-filter">Event type </label><select id="event-filter"><option value="all">All events</option><option value="model_call">Model API calls</option><option value="message">Agent messages</option><option value="tool_call">Tool calls</option><option value="tool_result">Tool results</option><option value="check">Code checks</option><option value="decision">Decisions</option></select><div id="trace-events">${evts.map(e=>`<details class="source-card trace-event" data-type="${esc(e.type)}"><summary><span class="tag">${String(e.seq).padStart(5,'0')}</span> ${esc(e.stage_id||'')} · ${esc(e.role||'code')} · ${esc(e.type)}</summary><pre><code>${esc(JSON.stringify(e,null,2))}</code></pre></details>`).join('')}</div>${record?`<details class="source-card"><summary>Complete run document</summary><pre>${esc(JSON.stringify(record,null,2))}</pre></details>`:''}`:`<div class="trace-empty" style="margin-top:22px"><strong>This run is real. Its full conversation is not in the public report.</strong><br>The report records its ID and result. Load the read-only MongoDB export in Evidence to inspect its exact messages and calls.</div>${r.case==='D2'&&r.arm==='baseline'?`<h3>The documented failure</h3><blockquote>${esc(exp.lesson.text)}</blockquote>`:''}<div class="source-row">${source(`reports/${exp.id}.md`,'Open the run table','Run ids by arm:')}</div>`}`,'RUN RECORD');}
async function importTrace(file){try{if(!file)return;if(file.size>80*1024*1024)throw new Error('The file exceeds 80 MB. Export only exp1 and exp2.');const data=JSON.parse(await file.text());if(!Array.isArray(data.runs)||!Array.isArray(data.events))throw new Error('Expected a JSON object with runs and events arrays. Use export_mongodb.py.');const ids=new Set(Object.values(DATA.experiments).flatMap(e=>e.runs.map(r=>r['run id'])));data.runs=data.runs.filter(r=>ids.has(r._id));data.events=data.events.filter(e=>ids.has(e.run_id));if(!data.runs.length||!data.events.length)throw new Error('No matching Experiment 1 or Experiment 2 run events were found.');if(data.events.some(e=>typeof e.seq!=='number'||typeof e.type!=='string'))throw new Error('An event is missing its sequence number or type.');rawExport=data;$('#import-status').textContent=`Loaded ${data.runs.length} matching runs and ${data.events.length} events. Open a run in Results to inspect the full conversation. Nothing has been uploaded.`;}catch(e){$('#import-status').textContent=`Could not load: ${e.message}`;}}
document.addEventListener('click',e=>{const b=e.target.closest('button, a.brand');if(!b)return;if(b.classList.contains('brand')){e.preventDefault();goScene(0);return}if(b.dataset.view)showView(b.dataset.view);else if(b.dataset.scene!==undefined)goScene(Number(b.dataset.scene));else if(b.dataset.source){if($('#drawer').open)$('#drawer').close();openSource(b.dataset.source,b.dataset.match||'')}else if(b.dataset.role)openRole(b.dataset.role);else if(b.dataset.evidence)openEvidence(b.dataset.evidence);else if(b.dataset.experiment){experiment=b.dataset.experiment;renderResults()}else if(b.dataset.collection){collection=b.dataset.collection;renderDatabase()}else if(b.dataset.run)openRun(b.dataset.run);else if(b.dataset.action==='coverage')openCoverage();else if(b.dataset.action==='goto-evidence'){$('#drawer').close();showView('sources')}});
document.addEventListener('change',e=>{if(e.target.id==='case-filter'){caseFilter=e.target.value;renderResults();$('#case-filter').focus()}if(e.target.id==='trace-file')importTrace(e.target.files[0]);if(e.target.id==='event-filter')$$('.trace-event').forEach(el=>el.hidden=e.target.value!=='all'&&el.dataset.type!==e.target.value)});
$('#prev').addEventListener('click',()=>goScene(scene-1));$('#next').addEventListener('click',()=>goScene(scene===scenes.length-1?0:scene+1));$('#play').addEventListener('click',play);$('#close-drawer').addEventListener('click',()=>$('#drawer').close());$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')){const r=$('#drawer').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#drawer').close()}});
document.addEventListener('keydown',e=>{if($('#drawer').open||view!=='story'||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();goScene(scene+1)}if(e.key==='ArrowLeft'){e.preventDefault();goScene(scene-1)}});
$('#fullscreen').addEventListener('click',async()=>{const entering=!document.body.classList.contains('presenting');document.body.classList.toggle('presenting',entering);$('#fullscreen').textContent=entering?'Exit presentation ↙':'Present ↗';window.scrollTo({top:0,behavior:'instant'});try{if(!entering&&document.fullscreenElement)await document.exitFullscreen();else if(entering&&!document.fullscreenElement)await document.documentElement.requestFullscreen()}catch{/* Compact presentation layout remains available when fullscreen is restricted. */}});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){document.body.classList.remove('presenting');$('#fullscreen').textContent='Present ↗'}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
$('#commit-id').textContent=DATA.commit.slice(0,7);
const initialHash=location.hash;const match=initialHash.match(/^#story-(\d+)$/);if(match)scene=Math.max(0,Math.min(scenes.length-1,Number(match[1])-1));renderScene();if(['#results','#database','#sources'].includes(initialHash))showView(initialHash.slice(1),false);
